# ==========================================================

@st.cache_resource
def load_artifacts():
    model = joblib.load("models/final_brake_wear_model.joblib")
    num_imp = joblib.load("data/regression_num_imputer.joblib")
    cat_imp = joblib.load("data/regression_cat_imputer.joblib")
    encoder = joblib.load("data/regression_encoder.joblib")
    scaler = joblib.load("data/regression_scaler.joblib")
    return model, num_imp, cat_imp, encoder, scaler


@st.cache_data
def load_evaluation():
    X = pd.read_csv("data/regression_X_test_scaled.csv")
    y = pd.read_csv("data/regression_y_test.csv").squeeze()

    model = joblib.load("models/final_brake_wear_model.joblib")
    pred = model.predict(X)

    return {
        "actual": np.asarray(y).ravel(),
        "pred": np.asarray(pred).ravel(),
        "mae": mean_absolute_error(y, pred),
        "rmse": np.sqrt(mean_squared_error(y, pred)),
        "r2": r2_score(y, pred),
    }


@st.cache_data
def load_dataset():
    return pd.read_csv("data/railway_cleaned.csv")


try:
    model, num_imp, cat_imp, encoder, scaler = load_artifacts()
    ev = load_evaluation()
except Exception as e:
    st.error("Model files could not be loaded. Check that the data and models folders are next to app.py.")
    st.code(str(e))
    st.stop()

