def predict(numeric, categorical):
    ndf = pd.DataFrame([numeric], columns=num_features)
    n = pd.DataFrame(num_imp.transform(ndf), columns=num_features)

    cdf = pd.DataFrame([categorical], columns=cat_features)
    c = pd.DataFrame(cat_imp.transform(cdf), columns=cat_features)

    encoded = encoder.transform(c)
    edf = pd.DataFrame(encoded, columns=encoder.get_feature_names_out(cat_features))

    combined = pd.concat([n, edf], axis=1)
    combined = combined.reindex(columns=scaler.feature_names_in_, fill_value=0)

    scaled = scaler.transform(combined)
    result = model.predict(scaled)[0]

    return float(np.clip(result, 0, 100))


def condition(value):
    if value < 25:
        return "Low wear", "#2EE6A6", "Pads are in good condition. Continue routine inspections."
    if value < 50:
        return "Moderate wear", CYAN, "Normal ageing. Plan a check at the next scheduled maintenance."
    if value < 75:
        return "High wear", "#FFB547", "Schedule an inspection soon and monitor this train more closely."
    return "Very high wear", "#FF4D5E", "Inspect before the next run and consider replacing the pads."


