def chart_style(fig, height=320):
    fig.update_layout(
        template="plotly_dark",
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Figtree", color="#BFD8E6", size=12),
        title=dict(font=dict(color="#FFFFFF", size=16), x=0.0),
        height=height,
        margin=dict(l=10, r=10, t=45, b=30),
        legend=dict(font=dict(color="#BFD8E6"), bgcolor="rgba(0,0,0,0)"),
        xaxis=dict(gridcolor="rgba(41,224,255,.07)", zeroline=False,
                   linecolor="rgba(41,224,255,.25)", tickfont=dict(color="#8FB0C4")),
        yaxis=dict(gridcolor="rgba(41,224,255,.09)", zeroline=False,
                   tickfont=dict(color="#8FB0C4")),
    )
    return fig


def error_by_band_fig():
    d = pd.DataFrame({
        "actual": ev["actual"],
        "err": np.abs(ev["actual"] - ev["pred"]),
    })
    d["band"] = pd.cut(
        d["actual"],
        [-np.inf, 25, 50, 75, np.inf],
        labels=["Low", "Moderate", "High", "Very high"],
    )
    g = d.groupby("band", observed=True)["err"].mean().reset_index()

    fig = go.Figure(go.Bar(
        x=g["band"].astype(str),
        y=g["err"],
        width=0.34,
        marker=dict(color=CYAN, line=dict(width=0)),
        hovertemplate="%{x}<br>Mean error %{y:.2f}<extra></extra>",
    ))

    fig.add_hline(
        y=ev["mae"], line_dash="dash", line_color=ORANGE, line_width=1.4,
        annotation_text="Overall average", annotation_position="top right",
        annotation_font=dict(color="#FFB27F", size=11),
    )

    chart_style(fig, 300)
    fig.update_layout(margin=dict(l=10, r=10, t=14, b=30), showlegend=False)
    fig.update_yaxes(title_text="Mean absolute error")
    return fig


def ring_fig():
    r = float(np.clip(ev["r2"], 0, 1)) * 100

    fig = go.Figure(go.Pie(
        values=[r / 2, r / 2, max(100 - r, 0.0001)],
        hole=0.85,
        sort=False,
        direction="clockwise",
        textinfo="none",
        hoverinfo="skip",
        marker=dict(
            colors=[CYAN, AZURE, "rgba(41,224,255,.12)"],
            line=dict(width=0),
        ),
    ))

    fig.add_annotation(text=f"<b>{ev['r2']:.3f}</b>", x=0.5, y=0.56, showarrow=False,
                       font=dict(size=36, color="#FFFFFF", family="Rajdhani"))
    fig.add_annotation(text="R² score", x=0.5, y=0.40, showarrow=False,
                       font=dict(size=13, color="#8FB0C4", family="Figtree"))

    fig.update_layout(
        height=230,
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        margin=dict(l=0, r=0, t=6, b=6),
        showlegend=False,
    )
    return fig


def actual_vs_pred_fig():
    a, p = ev["actual"], ev["pred"]
    order = np.argsort(a)
    idx = np.linspace(0, len(a) - 1, min(320, len(a))).astype(int)
    x = np.arange(len(idx))

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=x, y=a[order][idx], name="Actual wear", mode="lines",
        line=dict(color=CYAN, width=2.2),
        fill="tozeroy", fillcolor="rgba(41,224,255,.16)",
    ))
    fig.add_trace(go.Scatter(
        x=x, y=p[order][idx], name="Predicted wear", mode="lines",
        line=dict(color=ORANGE, width=1.8),
        fill="tozeroy", fillcolor="rgba(255,122,61,.08)",
    ))

    chart_style(fig, 300)
    fig.update_layout(
        margin=dict(l=10, r=10, t=10, b=34),
        legend=dict(orientation="h", y=1.12, x=1, xanchor="right"),
    )
    fig.update_xaxes(title_text="Test samples, sorted by actual wear", showticklabels=False)
    fig.update_yaxes(title_text="Wear (%)")
    return fig


def brake_assembly_3d():
    fig = go.Figure()

    theta = np.linspace(0, 2 * np.pi, 100)
    radius = np.linspace(1.0, 2.0, 18)
    T, R = np.meshgrid(theta, radius)

    # brake disc
    fig.add_trace(go.Surface(
        x=R * np.cos(T), y=R * np.sin(T), z=np.zeros_like(R),
        colorscale=[[0, "#31506B"], [.5, "#CFE6F5"], [1, "#4F7390"]],
        showscale=False, opacity=.97, hoverinfo="skip",
    ))

    # hub
    theta2 = np.linspace(0, 2 * np.pi, 80)
    r2 = np.linspace(.35, 1.0, 12)
    T2, R2 = np.meshgrid(theta2, r2)
    fig.add_trace(go.Surface(
        x=R2 * np.cos(T2), y=R2 * np.sin(T2), z=np.full_like(R2, .04),
        colorscale=[[0, "#0E6E8C"], [1, "#4FD6F5"]],
        showscale=False, opacity=1, hoverinfo="skip",
    ))

    # axle
    zz = np.linspace(-1.7, 1.7, 14)
    TT, ZZ = np.meshgrid(theta2, zz)
    fig.add_trace(go.Surface(
        x=.32 * np.cos(TT), y=.32 * np.sin(TT), z=ZZ,
        colorscale=[[0, "#39556E"], [1, "#9FB9CC"]],
        showscale=False, opacity=1, hoverinfo="skip",
    ))

    # brake pads on both sides of the disc
    px_pad = [1.15, 2.15, 2.15, 1.15, 1.15, 2.15, 2.15, 1.15]
    py_pad = [-.45, -.45, .45, .45, -.45, -.45, .45, .45]
    faces = [
        [0, 1, 2], [0, 2, 3], [4, 5, 6], [4, 6, 7],
        [0, 1, 5], [0, 5, 4], [1, 2, 6], [1, 6, 5],
        [2, 3, 7], [2, 7, 6], [3, 0, 4], [3, 4, 7],
    ]
    ii, jj, kk = zip(*faces)

    for sign in (1, -1):
        pz = [sign * z for z in (.12, .12, .12, .12, .42, .42, .42, .42)]
        fig.add_trace(go.Mesh3d(
            x=px_pad, y=py_pad, z=pz, i=ii, j=jj, k=kk,
            color=ORANGE, opacity=1, flatshading=True, name="Brake pad",
        ))

    fig.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        height=340,
        margin=dict(l=0, r=0, t=0, b=0),
        scene=dict(
            bgcolor="rgba(0,0,0,0)",
            xaxis=dict(visible=False),
            yaxis=dict(visible=False),
            zaxis=dict(visible=False),
            aspectmode="data",
            camera=dict(eye=dict(x=1.8, y=1.7, z=1.2)),
        ),
        showlegend=False,
    )
    return fig


